{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@max10240/opencode-plugin-image-gen",
  "version": "1.0.26",
  "description": "Generate and edit images in OpenCode through provider Images APIs",
  "type": "module",
  "exports": {
    ".": "./dist/src/index.js"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "build": "tsc -p tsconfig.build.json",
    "prepack": "node ../../scripts/sync-recommended-rules.mjs && npm run build"
  },
  "files": [
    "dist/**/*.js",
    "README.md",
    "README.zh-CN.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "image-generation",
    "openai-images"
  ],
  "license": "MIT",
  "dependencies": {
    "@opencode/ai": "^2.2.0",
    "@opencode/plugin": "^2.2.7",
    "effect": "^4.0.1"
  },
  "devDependencies": {
    "@types/bun": "^1.3.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.8.2"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Max10240/opencode-plugin-unicorn.git",
    "directory": "packages/opencode-plugin-image-gen"
  }
}
